import{_ as i,c as a,o as n,ah as t}from"./chunks/framework.BaqsfJuc.js";const h=JSON.parse('{"title":"Sideband Relay Protocol Compliance Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"specs/secure-relay-protocol-compliance.md","filePath":"specs/secure-relay-protocol-compliance.md","lastUpdated":0}'),o={name:"specs/secure-relay-protocol-compliance.md"};function l(r,e,s,c,d,m){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="sideband-relay-protocol-compliance-checklist" tabindex="-1">Sideband Relay Protocol Compliance Checklist <a class="header-anchor" href="#sideband-relay-protocol-compliance-checklist" aria-label="Permalink to “Sideband Relay Protocol Compliance Checklist”">​</a></h1><p>Use this checklist to verify conformance with <code>secure-relay-protocol.md</code>. Items tagged MUST/SHOULD mirror normative requirements.</p><h2 id="common-crypto-client-daemon" tabindex="-1">Common Crypto (Client + Daemon) <a class="header-anchor" href="#common-crypto-client-daemon" aria-label="Permalink to “Common Crypto (Client + Daemon)”">​</a></h2><ul><li>[ ] MUST use Ed25519 for daemon identity and X25519 for ephemeral key exchange.</li><li>[ ] MUST sign handshake payload <code>SHA256(&quot;sbrp-v1-handshake&quot; || daemonId || clientPublicKey || daemonPublicKey)</code>.</li><li>[ ] MUST compute transcript hash <code>SHA256(&quot;sbrp-v1-transcript&quot; || daemonId || clientPublicKey || daemonPublicKey || signature)</code> and use it as HKDF-SHA256 salt.</li><li>[ ] MUST set HKDF <code>info</code> to the constant <code>&quot;sbrp-session-keys&quot;</code> and <code>len = 64</code>.</li><li>[ ] MUST derive directional keys <code>clientToDaemon</code> and <code>daemonToClient</code>.</li><li>[ ] MUST build nonce as 12 bytes: 4-byte direction constant + 8-byte big-endian seq.</li><li>[ ] MUST start sequence numbers at 0 and increment per message per direction.</li><li>[ ] MUST reject messages outside the replay window; MUST use bitmap window &gt;= 64 and SHOULD use &gt;= 128.</li><li>[ ] MUST preserve sequence state on resume without handshake; if lost, MUST force full handshake.</li></ul><h2 id="client-ui" tabindex="-1">Client (UI) <a class="header-anchor" href="#client-ui" aria-label="Permalink to “Client (UI)”">​</a></h2><ul><li>[ ] MUST pin daemon identity public key on first connection (TOFU).</li><li>[ ] MUST persist pins across page reloads (for browser clients); SHOULD survive application restarts.</li><li>[ ] MUST abort on identity mismatch with <code>identity_key_changed</code> and require explicit user approval to accept new key.</li><li>[ ] MUST present both stored and new fingerprints on <code>identity_key_changed</code>.</li><li>[ ] MUST verify daemon signature using pinned identity key, not relay-provided key.</li><li>[ ] MUST perform a full handshake on client reconnect (new ephemeral keys).</li><li>[ ] SHOULD warn when storage is unavailable or ephemeral (private/incognito).</li></ul><h2 id="daemon-agent" tabindex="-1">Daemon (Agent) <a class="header-anchor" href="#daemon-agent" aria-label="Permalink to “Daemon (Agent)”">​</a></h2><ul><li>[ ] MUST generate and persist a long-lived Ed25519 identity keypair; register public key with relay.</li><li>[ ] MUST sign its ephemeral X25519 public key in <code>handshake.accept</code>.</li><li>[ ] MUST maintain per-client session state (keys, seq, replay window) independently.</li><li>[ ] MUST resume with the same keys and sequence state if relay session is resumed.</li><li>[ ] MUST re-handshake if sequence state is lost before resuming encrypted traffic.</li><li>[ ] MUST NOT resume a session after process restart or loss of volatile memory.</li><li>[ ] SHOULD store identity keys with restrictive permissions (e.g., 0600).</li><li>[ ] SHOULD best-effort zeroize ephemeral key material after use.</li></ul><h2 id="relay" tabindex="-1">Relay <a class="header-anchor" href="#relay" aria-label="Permalink to “Relay”">​</a></h2><ul><li>[ ] MUST authenticate user sessions and daemon API keys.</li><li>[ ] MUST enforce user → daemon ownership on connections.</li><li>[ ] MUST provide daemon identity public keys to clients for TOFU pinning.</li><li>[ ] MUST forward handshake and encrypted messages without modification or inspection.</li><li>[ ] SHOULD rate-limit connections and message throughput.</li><li>[ ] If reconnection grace is implemented, MUST pause routing when daemon disconnects and resume only within the grace window; otherwise MUST require a new handshake.</li></ul><h2 id="optional-quick-connect" tabindex="-1">Optional: Quick Connect <a class="header-anchor" href="#optional-quick-connect" aria-label="Permalink to “Optional: Quick Connect”">​</a></h2><ul><li>[ ] MUST issue time-limited codes (5 minutes) and perform normal E2EE handshake.</li><li>[ ] SHOULD warn that Quick Connect provides reduced authentication guarantees.</li></ul>',12)])])}const u=i(o,[["render",l]]);export{h as __pageData,u as default};
